enum class R { SUCCESS, RETRY, FAILURE }

fun doWork(attempt: Int, online: Boolean): R = when {
    attempt >= 3 -> R.FAILURE
    !online -> R.RETRY
    else -> R.SUCCESS
}

fun main() {
    val online = listOf(false, false, false, true)
    var attempt = 0
    while (true) {
        val r = doWork(attempt, online[attempt])
        println("$attempt $r")
        if (r != R.RETRY) break
        attempt++
    }
}

