@Singleton
class CartBadge @Inject constructor() {
    var listener: ((Int) -> Unit)? = null
}

@AndroidEntryPoint
class MainActivity : ComponentActivity() {
    @Inject lateinit var badge: CartBadge
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        val label = TextView(this)
        badge.listener = { label.text = "$it" }
        setContentView(label)
    }
}

override suspend fun load(type: LoadType, state: PagingState<Int, Post>): MediatorResult {
    val page = pageFor(type, state) ?: return MediatorResult.Success(true)
    val posts = api.feed(page)
    if (type == LoadType.REFRESH) db.postDao().clearAll()
    db.postDao().insertAll(posts)
    return MediatorResult.Success(endOfPaginationReached = posts.isEmpty())
}
